    if not os.path.exists(pf): continue
    prs=json.load(open(jf))
    spec=importlib.util.spec_from_file_location(tid.replace('-','_')+'_v',pf)
    t=importlib.util.module_from_spec(spec)
    try:
        spec.loader.exec_module(t)
        ok=all(t.transform(p['input'])==p['output'] for p in prs)
        results[tid]='ok' if ok else 'MISMATCH'
    except Exception as e:
        results[tid]='ERROR '+str(e)
print(results)
